# ---------- 캐시 / 네트워크 ----------
_cache, _clock = {}, threading.Lock()


def cached(key, ttl, fn):
    now = time.time()
    with _clock:
        hit = _cache.get(key)
        if hit and now - hit[0] < ttl:
            return hit[1]
    val = fn()
    with _clock:
        _cache[key] = (time.time(), val)
    return val


def fetch_json(url):
    req = urllib.request.Request(url, headers=UA)
    with urllib.request.urlopen(req, timeout=12) as r:
        return json.loads(r.read().decode())


def get_chart(sym, rng="1d", interval="5m"):
    if not SYM_RE.match(sym):
        raise ValueError("잘못된 종목 코드")
    ttl = 4 if interval in ("1m", "2m", "5m") else 300

    def f():
        j = fetch_json(f"https://query1.finance.yahoo.com/v8/finance/chart/{urllib.parse.quote(sym)}"
                       f"?range={rng}&interval={interval}")
        r = j["chart"]["result"][0]
        meta = r["meta"]
        q = r["indicators"]["quote"][0]
        rows = []
        for t, o, h, l, c, v in zip(r.get("timestamp") or [], q["open"], q["high"], q["low"], q["close"], q["volume"]):
            if c is None:
                continue
            rows.append({"t": t, "o": o if o is not None else c, "h": h if h is not None else c,
                         "l": l if l is not None else c, "c": c, "v": v or 0})
        price = meta.get("regularMarketPrice") or (rows[-1]["c"] if rows else None)
        return {"symbol": sym, "price": price, "prev": meta.get("chartPreviousClose") or meta.get("previousClose"),
                "state": meta.get("marketState", ""), "rows": rows}

    return cached(("chart", sym, rng, interval), ttl, f)


def get_news(sym):
    def f():
        try:
            j = fetch_json(f"https://query1.finance.yahoo.com/v1/finance/search?q={urllib.parse.quote(sym)}"
                           f"&quotesCount=0&newsCount=8")
            return [{"title": n.get("title", ""), "publisher": n.get("publisher", ""),
                     "link": n.get("link", ""), "time": n.get("providerPublishTime", 0)}
                    for n in j.get("news", [])]
        except Exception:
            return []
    return cached(("news", sym), 900, f)


# ---------- 기술적 지표 ----------
def sma(x, n):
    out, s = [None] * len(x), 0.0
    for i, v in enumerate(x):
        s += v
        if i >= n:
            s -= x[i - n]
        if i >= n - 1:
            out[i] = s / n
    return out


def ema(x, n):
    k = 2 / (n + 1)
    out = [x[0]]
    for v in x[1:]:
        out.append(out[-1] + k * (v - out[-1]))
    return out


def rsi(x, n=14):
    out = [None] * len(x)
    if len(x) <= n:
        return out
    ag = sum(max(x[i] - x[i - 1], 0) for i in range(1, n + 1)) / n
    al = sum(max(x[i - 1] - x[i], 0) for i in range(1, n + 1)) / n
    out[n] = 100 if al == 0 else 100 - 100 / (1 + ag / al)
    for i in range(n + 1, len(x)):
        d = x[i] - x[i - 1]
        ag = (ag * (n - 1) + max(d, 0)) / n
        al = (al * (n - 1) + max(-d, 0)) / n
        out[i] = 100 if al == 0 else 100 - 100 / (1 + ag / al)
    return out


def prep(rows):
    c = [r["c"] for r in rows]
    v = [r["v"] for r in rows]
    n = len(c)
    e12, e26 = ema(c, 12), ema(c, 26)
    macd = [a - b for a, b in zip(e12, e26)]
    hist = [a - b for a, b in zip(macd, ema(macd, 9))]
    vs5, vs20 = sma(v, 5), sma(v, 20)
    vr = [(vs5[i] / vs20[i]) if (vs5[i] and vs20[i]) else 1.0 for i in range(n)]
    return {"c": c, "s20": sma(c, 20), "s50": sma(c, 50), "rsi": rsi(c, 14), "hist": hist, "vr": vr}


def score_at(S, i):
    """i 시점까지의 데이터만 사용 (미래 참조 없음). 점수 범위 대략 -90 ~ +90"""
    if i < 50:
        return None, []
    c = S["c"]
    parts = []

    def add(t, p):
        parts.append({"text": t, "pts": round(p, 1)})

    add("현재가 20일선 위" if c[i] > S["s20"][i] else "현재가 20일선 아래", 15 if c[i] > S["s20"][i] else -15)
    add("중기 상승추세(20일선 > 50일선)" if S["s20"][i] > S["s50"][i] else "중기 하락추세(20일선 < 50일선)",
        15 if S["s20"][i] > S["s50"][i] else -15)
    r = S["rsi"][i]
    if r < 30:
        add(f"RSI {r:.0f} 과매도 → 반등 가능성", 20)
    elif r > 70:
        add(f"RSI {r:.0f} 과매수 → 조정 가능성", -20)
    elif r >= 50:
        add(f"RSI {r:.0f} 강세권", 5)
    else:
        add(f"RSI {r:.0f} 약세권", -5)
    h = S["hist"]
    if h[i] > 0 and h[i] > h[i - 1]:
        add("MACD 양수 & 상승 중", 15)
    elif h[i] < 0 and h[i] < h[i - 1]:
        add("MACD 음수 & 하락 중", -15)
    elif h[i] > 0:
        add("MACD 양수지만 둔화", 5)
    else:
        add("MACD 음수지만 회복 조짐", -5)
    r5 = c[i] / c[i - 5] - 1
    add(f"최근 5거래일 수익률 {r5 * 100:+.1f}%", max(-15, min(15, r5 * 150)))
    vr = S["vr"][i]
    if vr > 1.5 and r5 > 0:
        add(f"거래량 평균 대비 {vr:.1f}배 급증 + 상승", 10)
    elif vr > 1.5 and r5 < 0:
        add(f"거래량 {vr:.1f}배 급증 + 하락(매도 압력)", -10)
    return round(sum(p["pts"] for p in parts), 1), parts


POS_W = ["surge", "soar", "beat", "record", "upgrade", "jump", "rally", "gain", "partnership", "approval",
         "wins", "deal", "raises", "growth", "bullish", "rise", "tops", "contract", "breakthrough", "jumps"]
NEG_W = ["plunge", "fall", "drop", "downgrade", "lawsuit", "miss", "cut", "probe", "loss", "slump", "warn",
         "bearish", "decline", "short", "sell-off", "selloff", "dilution", "offering", "tumble", "sinks"]


def news_bonus(items):
    pos = neg = 0
    for it in items:
        t = it["title"].lower()
        pos += sum(w in t for w in POS_W)
        neg += sum(w in t for w in NEG_W)
    return max(-10, min(10, (pos - neg) * 3)), pos, neg


def analyze_core(sym):
    """기술적 분석 + 과거 1년 '같은 점수였던 날들'의 5거래일 뒤 실제 결과 목록"""
    d = get_chart(sym, "1y", "1d")
    rows = d["rows"]
    if len(rows) < 70:
        raise ValueError(f"{sym}: 데이터 부족")
    S = prep(rows)
    c = S["c"]
    n = len(c)
    tech, parts = score_at(S, n - 1)
    hs = []
    for j in range(50, n - 5):
        sc, _ = score_at(S, j)
        hs.append((sc, c[j + 5] > c[j]))
    tr = rows[-14:]
    atr = sum((r["h"] - r["l"]) / r["c"] for r in tr) / len(tr)
    price = d["price"] or c[-1]
    return {"symbol": sym, "name": NAMES.get(sym, sym), "price": price,
            "change_pct": round((price / c[-2] - 1) * 100, 2), "tech": tech, "parts": parts,
            "hs": hs, "atr": atr, "market_state": d["state"]}


def smooth_p(hs, tech, width=12, m=10):
    """비슷한 점수(±12)였던 과거 날들의 상승 비율. 표본이 적으면 50% 쪽으로 보정(베이지안 평활)."""
    near = [up for s, up in hs if abs(s - tech) <= width]
    k, nn = sum(near), len(near)
    return (k + 0.5 * m) / (nn + m), nn


def judge(p_up):
    if p_up >= 0.55:
        return "LONG"
    if p_up <= 0.45:
        return "SHORT"
    return "WAIT"


def phrase(rec, p_up):
    if rec == "LONG":
        return f"오를 것 같습니다 (상승 확률 {p_up * 100:.0f}%)"
    if rec == "SHORT":
        return f"내릴 것 같습니다 (하락 확률 {(1 - p_up) * 100:.0f}%)"
    return f"방향 불확실 (상승 확률 {p_up * 100:.0f}%)"


def build(a, news):
    nb, pos, neg = news_bonus(news)
    p_tech, nn = smooth_p(a["hs"], a["tech"])
    p_up = min(0.98, max(0.02, p_tech + nb / 200))  # 뉴스 심리는 최대 ±5%p 반영
    rec = judge(p_up)
    parts = list(a["parts"])
    if nb:
        parts.append({"text": f"뉴스 제목 심리 (긍정 {pos} / 부정 {neg})", "pts": nb})
    total = round(a["tech"] + nb, 1)
    price = a["price"]
    stop = None
    if rec == "LONG":
        stop = round(price * (1 - 2 * a["atr"]), 2)
    elif rec == "SHORT":
        stop = round(price * (1 + 2 * a["atr"]), 2)
    return {"symbol": a["symbol"], "name": a["name"], "price": price, "change_pct": a["change_pct"],
            "tech": a["tech"], "news_bonus": nb, "score": total, "p_up": round(p_up, 3),
            "side": round(p_up if rec != "SHORT" else 1 - p_up, 3), "rec": rec,
            "text": phrase(rec, p_up), "sample": nn, "parts": parts, "news": news[:8], "stop": stop,
            "atr_pct": round(a["atr"] * 100, 2), "market_state": a["market_state"]}


def analyze(sym):
    if not SYM_RE.match(sym):
        raise ValueError("잘못된 종목 코드")
    return cached(("an", sym), 300, lambda: build(analyze_core(sym), get_news(sym)))


def summary():
    def one(item):
        sym, name = item
        try:
            a = analyze(sym)
            return {"symbol": sym, "name": name, "rec": a["rec"], "p_up": a["p_up"], "side": a["side"],
                    "text": a["text"], "sample": a["sample"]}
        except Exception as e:
            return {"symbol": sym, "name": name, "error": str(e)}
    with ThreadPoolExecutor(8) as ex:
        return list(ex.map(one, WATCH))


def search(q):
    q = q.strip()[:40]
    if not q:
        return []
    j = fetch_json(f"https://query1.finance.yahoo.com/v1/finance/search?q={urllib.parse.quote(q)}"
                   f"&quotesCount=8&newsCount=0")
    out = []
    for it in j.get("quotes", []):
        sym = it.get("symbol", "")
        if it.get("quoteType") in ("EQUITY", "ETF", "CRYPTOCURRENCY") and SYM_RE.match(sym):
            out.append({"symbol": sym, "name": it.get("shortname") or it.get("longname") or sym,
                        "type": it.get("quoteType"), "exchange": it.get("exchDisp", "")})
    return out


def watch_quotes():
    def one(sym):
        try:
            d = get_chart(sym, "1d", "5m")
            p, prev = d["price"], d["prev"]
            return {"symbol": sym, "name": NAMES[sym], "price": p,
                    "change_pct": round((p / prev - 1) * 100, 2) if prev else None}
        except Exception:
            return {"symbol": sym, "name": NAMES[sym], "price": None, "change_pct": None}
    with ThreadPoolExecutor(10) as ex:
        return list(ex.map(one, [s for s, _ in WATCH]))


# ---------- 신규 주식 찾기 (백그라운드 스캔) ----------
SCAN = {"running": False, "stage": "대기 중", "done": 0, "total": 0, "elapsed": 0.0, "eta": None,
        "results": [], "note": "", "finished": False, "limit": TIME_LIMIT, "error": None}
SCAN_LOCK = threading.Lock()


def load_shown():
    try:
        return json.load(open(SHOWN_FILE))
    except Exception:
        return []


def save_shown(lst):
    json.dump(lst, open(SHOWN_FILE, "w"), ensure_ascii=False, indent=1)


def run_scan():
    t0 = time.time()
    deadline = t0 + TIME_LIMIT

    def upd(**kw):
        with SCAN_LOCK:
            SCAN.update(kw)
            SCAN["elapsed"] = round(time.time() - t0, 1)

    try:
        shown = set(load_shown())
        excl = {s for s, _ in WATCH} | shown
        cands = [(s, n) for s, n in SCAN_UNIVERSE if s not in excl]
        upd(stage="1단계: 후보 종목 과거 1년 데이터 분석", done=0, total=len(cands), results=[],
            finished=False, eta=None,
            note=f"관심 20종목 및 이전에 보여준 {len(shown)}개 종목은 제외했습니다.")
        times, W = [], 8

        def work(item):
            if time.time() > deadline:
                return None
            ts = time.time()
            try:
                a = analyze_core(item[0])
            except Exception:
                a = None
            times.append(time.time() - ts)
            return a

        scored = []
        with ThreadPoolExecutor(W) as ex:
            futs = [ex.submit(work, it) for it in cands]
            for k, f in enumerate(as_completed(futs)):
                a = f.result()
                if a:
                    scored.append((smooth_p(a["hs"], a["tech"])[0], a))
                avg = sum(times) / len(times) if times else 1.0
                upd(done=k + 1, eta=round(avg * (len(cands) - k - 1) / W, 1))
        scored.sort(key=lambda x: x[0], reverse=True)
        top = [a for _, a in scored[:15]]

        upd(stage="2단계: 상위 후보 뉴스 종합", eta=None, done=0, total=len(top))

        def fin(a):
            if time.time() > deadline:
                return None
            return build(a, get_news(a["symbol"]))

        views = []
        with ThreadPoolExecutor(W) as ex:
            for k, v in enumerate(ex.map(fin, top)):
                if v:
                    views.append(v)
                upd(done=k + 1)

        views.sort(key=lambda v: v["p_up"], reverse=True)
        strong = [v for v in views if v["rec"] == "LONG"]
        weak = [v for v in views if v["rec"] != "LONG"]
        picks = []
        for v in strong[:5]:
            picks.append({**v, "strength": "강함" if v["p_up"] >= 0.6 else "보통"})
        for v in weak[:5 - len(picks)]:
            picks.append({**v, "strength": "약함(신호 부족, 참고용)"})
        picks = [{k: p[k] for k in ("symbol", "name", "price", "change_pct", "p_up", "side", "rec", "text",
                                    "sample", "strength", "stop", "atr_pct", "news", "parts")} for p in picks]
        for p in picks:
            p["reasons"] = [x["text"] for x in p.pop("parts") if x["pts"] > 0]
            p["news"] = p["news"][:3]
        save_shown(sorted(shown | {p["symbol"] for p in picks}))
        el = round(time.time() - t0, 1)
        n_strong = sum(1 for p in picks if p["rec"] == "LONG")
        note = f"완료: {el:.0f}초 소요 (제한 {TIME_LIMIT}초)."
        if time.time() > deadline:
            note += " 시간 제한에 맞춰 일부 종목만 분석했습니다."
        if n_strong < 5:
            note += f" 상승 신호가 뚜렷한 종목은 {n_strong}개뿐이라 나머지는 '약함'으로 표시했습니다."
        upd(results=picks, finished=True, running=False, stage="완료", eta=0, note=note)
    except Exception as e:
        upd(error=str(e), finished=True, running=False, stage="오류")


def get_asset(name):
    """내장 파일(ASSETS) 우선, 없으면 디스크에서 읽기"""
    if name in ASSETS:
        return base64.b64decode(ASSETS[name])
    with open(os.path.join(STATIC, name), "rb") as f:
        return f.read()


# ---------- HTTP ----------
class H(BaseHTTPRequestHandler):
    server_version = "PrivateStock"

    def log_message(self, *a):
        pass

    def authed(self):
        c = SimpleCookie(self.headers.get("Cookie", ""))
        m = c.get("sess")
        return bool(m) and hmac.compare_digest(m.value, SESSION)

    def send(self, code, body, ctype="application/json", headers=None):
        if isinstance(body, (dict, list)):
            body = json.dumps(body, ensure_ascii=False).encode()
        elif isinstance(body, str):
            body = body.encode()
        self.send_response(code)
        ct = ctype + ("; charset=utf-8" if ctype.startswith("text/") or ctype == "application/json" else "")
        self.send_header("Content-Type", ct)
        self.send_header("Content-Length", str(len(body)))
        self.send_header("Cache-Control", "no-store")
        for k, v in (headers or {}).items():
            self.send_header(k, v)
        self.end_headers()
        self.wfile.write(body)

    def page(self, name):
        self.send(200, get_asset(name), "text/html")

    def redirect(self, loc):
        self.send(302, b"", "text/plain", {"Location": loc})

    def do_GET(self):
        self.route("GET")

    def do_POST(self):
        self.route("POST")

    def route(self, method):
        u = urllib.parse.urlparse(self.path)
        q = dict(urllib.parse.parse_qsl(u.query))
        p = u.path
        try:
            if p == "/login":
                return self.page("login.html") if not self.authed() else self.redirect("/")
            if p == "/api/login" and method == "POST":
                n = int(self.headers.get("Content-Length", 0) or 0)
                body = json.loads(self.rfile.read(n) or b"{}")
                if hmac.compare_digest(str(body.get("password", "")), PASSWORD):
                    return self.send(200, {"ok": True}, headers={
                        "Set-Cookie": f"sess={SESSION}; Path=/; HttpOnly; SameSite=Strict; Max-Age=2592000"})
                return self.send(403, {"error": "비밀번호가 틀렸습니다"})
            if p == "/api/logout":
                return self.send(200, {"ok": True}, headers={"Set-Cookie": "sess=; Path=/; Max-Age=0"})
            if p == "/":
                return self.page("index.html") if self.authed() else self.redirect("/login")
            if p == "/scan":
                return self.page("scan.html") if self.authed() else self.redirect("/login")
            if p.startswith("/static/"):
                fn = os.path.basename(p)
                if fn not in ("common.js", "index.js", "scan.js", "style.css"):
                    return self.send(404, {"error": "not found"})
                ctype = {"js": "application/javascript", "css": "text/css"}.get(fn.rsplit(".", 1)[-1], "text/plain")
                return self.send(200, get_asset(fn), ctype)
            if p.startswith("/api/"):
                if not self.authed():
                    return self.send(401, {"error": "login required"})
                if p == "/api/watch":
                    return self.send(200, cached("watch", 4, watch_quotes))
                if p == "/api/summary":
                    return self.send(200, cached("summary", 300, summary))
                if p == "/api/search":
                    return self.send(200, search(q.get("q", "")))
                if p == "/api/chart":
                    return self.send(200, get_chart(q.get("symbol", "NVDA"), q.get("range", "1d"),
                                                    q.get("interval", "5m")))
                if p == "/api/analyze":
                    return self.send(200, analyze(q.get("symbol", "")))
                if p == "/api/scan/start" and method == "POST":
                    with SCAN_LOCK:
                        if not SCAN["running"]:
                            SCAN.update(running=True, results=[], finished=False, error=None,
                                        stage="시작 중", done=0, total=0, eta=None, elapsed=0.0)
                            threading.Thread(target=run_scan, daemon=True).start()
                    return self.send(200, dict(SCAN))
                if p == "/api/scan/status":
                    with SCAN_LOCK:
                        return self.send(200, dict(SCAN))
                if p == "/api/shown/reset" and method == "POST":
                    save_shown([])
                    return self.send(200, {"ok": True})
            return self.send(404, {"error": "not found"})
        except Exception as e:
            return self.send(500, {"error": str(e)})


if __name__ == "__main__":
    srv = ThreadingHTTPServer(("0.0.0.0", int(os.environ.get("PORT", 8000))), H)
    print("비밀번호 파일:", PW_FILE, flush=True)
    print("서버 실행 중", flush=True)
    srv.serve_forever()
